    /// <summary>
    /// Sends an upgraded gift to another user or channel chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> TransferGiftAsync(string businessConnectionId = default, string receivedGiftId = default, MessageSender newOwnerId = default, long starCount = default)
    {

           using var activity =  StartCallActivity("TransferGiftAsync", typeof(TransferGift).FullName ?? "TransferGiftAsync");

           try
           {
             return client.TransferGiftAsync(businessConnectionId, receivedGiftId, newOwnerId, starCount);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
